<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\{TechnicianProfile,User}; use Illuminate\Http\{JsonResponse,Request};
class TechnicianController extends Controller {
 public function index(Request $r):JsonResponse{$q=User::where('role','technician')->whereHas('technicianProfile',fn($x)=>$x->where('kyc_status','approved')->where('is_available',true))->with(['technicianProfile','categories']);if($r->filled('category'))$q->whereHas('categories',fn($x)=>$x->where('slug',$r->string('category')));if($r->filled('state'))$q->whereHas('technicianProfile',fn($x)=>$x->where('state',$r->string('state')));if($r->filled('city'))$q->whereHas('technicianProfile',fn($x)=>$x->where('city',$r->string('city')));return response()->json($q->paginate(min((int)$r->input('per_page',20),50)));}
 public function show(User $technician):JsonResponse{abort_unless($technician->role->value==='technician',404);return response()->json(['data'=>$technician->load(['technicianProfile','categories'])]);}
 public function upsertProfile(Request $r):JsonResponse{abort_unless($r->user()->role->value==='technician',403);$d=$r->validate(['trade'=>'required|string|max:120','business_name'=>'nullable|string|max:160','bio'=>'nullable|string|max:3000','years_experience'=>'required|integer|min:0|max:80','city'=>'required|string|max:100','state'=>'required|string|max:100','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180','is_available'=>'sometimes|boolean','category_ids'=>'array','category_ids.*'=>'exists:service_categories,id']);$ids=$d['category_ids']??[];unset($d['category_ids']);$p=TechnicianProfile::updateOrCreate(['user_id'=>$r->user()->id],$d);$r->user()->categories()->sync($ids);return response()->json(['data'=>$p->load('user')]);}
}
